//! Tagged finite contribution quotients generated by supplied matched-slot pairs.
//! Object/local-position tags identify vertices; payload equality is irrelevant.
//! Matched action slots connect recognized tags, yielding dense component indices.
//! Category/bifunctor admission and adequacy as a dinaturality encoding are caller
//! obligations; these raw action tables do not certify a universal coend.
//! Missing/unrecognized relations are ignored by construction and may be observed
//! by the separate presence/local-label diagnostics. AuthorityEffect: None.

use std::collections::BTreeMap;

// ---------------------------------------------------------------------------
// DinaturalityWitness — records one identification
// ---------------------------------------------------------------------------

/// One supplied matched-slot identification of two recognized position tags.
/// Morphism names and intended boundaries are caller metadata.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DinaturalityWitness {
    /// The morphism f: source → target that induced this identification.
    pub morphism: String,
    pub source_object: String,
    pub target_object: String,
    /// Index of the element in the forward contribution.
    pub forward_index: usize,
    /// Index of the element in the backward contribution.
    pub backward_index: usize,
}

// ---------------------------------------------------------------------------
// DeclaredFiniteCoend
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct TaggedDiagonal<T> {
    pub object: String,
    pub index: usize,
    pub value: T,
}

/// Raw tagged-position partition and copied supplied metadata.
/// Classes are ordered by their first position in the declared object inventory;
/// members retain that position order. No category/bifunctor certificate is stored.
#[derive(Debug, Clone)]
pub struct DeclaredFiniteCoend<T: Clone + PartialEq> {
    /// The contributing objects (diagonal entries of the bifunctor).
    pub objects: Vec<String>,
    /// All raw supplied diagonal contributions, including undeclared-object data.
    pub contributions: BTreeMap<String, Vec<T>>,
    /// Nonempty classes of recognized unique tags after the supplied identifications.
    pub classes: Vec<Vec<TaggedDiagonal<T>>>,
    /// Maps a tagged diagonal element (object, index) to its equivalence class index.
    pub class_of: BTreeMap<(String, usize), usize>,
    /// Dinaturality identifications applied during computation.
    pub identifications: Vec<DinaturalityWitness>,
}

/// Input for computing a finite coend.
pub struct CoendInput<T: Clone + PartialEq> {
    /// Declared object names; repetitions refer to the same diagonal positions.
    pub objects: Vec<String>,
    /// Declared relation rows: (name, source, target), without category-law admission.
    pub morphisms: Vec<(String, String, String)>,
    /// Diagonal contributions: object → elements of F(c,c).
    pub diagonal: BTreeMap<String, Vec<T>>,
    /// Name → (source-local position, slot label). Slot labels are compared literally.
    pub forward_action: BTreeMap<String, Vec<(usize, usize)>>,
    /// Name → (target-local position, slot label); equal slots generate a relation.
    pub backward_action: BTreeMap<String, Vec<(usize, usize)>>,
}

type TagIndex<'a> = BTreeMap<(&'a str, usize), usize>;

fn append_diagonal<'a, T: Clone>(
    object: &'a str,
    values: &[T],
    elements: &mut Vec<TaggedDiagonal<T>>,
    index: &mut TagIndex<'a>,
) {
    for (local, value) in values.iter().enumerate() {
        if index.contains_key(&(object, local)) {
            continue;
        }
        index.insert((object, local), elements.len());
        elements.push(TaggedDiagonal { object: object.to_owned(), index: local, value: value.clone() });
    }
}

fn tagged_elements<T: Clone + PartialEq>(input: &CoendInput<T>) -> (Vec<TaggedDiagonal<T>>, TagIndex<'_>) {
    let mut elements = Vec::new();
    let mut index = BTreeMap::new();
    for object in &input.objects {
        if let Some(values) = input.diagonal.get(object) {
            append_diagonal(object, values, &mut elements, &mut index);
        }
    }
    (elements, index)
}

fn matched_pairs<'a>(
    forward: &'a [(usize, usize)],
    backward: &'a [(usize, usize)],
) -> impl Iterator<Item = (usize, usize)> + 'a {
    forward.iter().flat_map(move |&(source, slot)| {
        backward.iter().filter_map(move |&(target, other)| {
            (slot == other).then_some((source, target))
        })
    })
}

fn identify_morphism(
    row: &(String, String, String),
    forward: &[(usize, usize)],
    backward: &[(usize, usize)],
    index: &TagIndex<'_>,
    adjacency: &mut [Vec<usize>],
    witnesses: &mut Vec<DinaturalityWitness>,
) {
    let (name, source, target) = row;
    for (source_local, target_local) in matched_pairs(forward, backward) {
        let (Some(&a), Some(&b)) = (index.get(&(source.as_str(), source_local)), index.get(&(target.as_str(), target_local))) else {
            continue;
        };
        if a != b {
            adjacency[a].push(b);
            adjacency[b].push(a);
        }
        witnesses.push(DinaturalityWitness {
            morphism: name.clone(), source_object: source.clone(), target_object: target.clone(),
            forward_index: source_local, backward_index: target_local,
        });
    }
}

fn relation_graph<T: Clone + PartialEq>(
    input: &CoendInput<T>, index: &TagIndex<'_>, count: usize,
) -> (Vec<Vec<usize>>, Vec<DinaturalityWitness>) {
    let mut adjacency = vec![Vec::new(); count];
    let mut witnesses = Vec::new();
    for row in &input.morphisms {
        if let (Some(forward), Some(backward)) = (input.forward_action.get(&row.0), input.backward_action.get(&row.0)) {
            identify_morphism(row, forward, backward, index, &mut adjacency, &mut witnesses);
        }
    }
    (adjacency, witnesses)
}

// Callers construct closed adjacency and equal-length labels from the same tag index.
fn flood_component(adjacency: &[Vec<usize>], labels: &mut [usize], root: usize, class: usize) {
    labels[root] = class;
    let mut pending = vec![root];
    while let Some(vertex) = pending.pop() {
        for &next in &adjacency[vertex] {
            if labels[next] == usize::MAX {
                labels[next] = class;
                pending.push(next);
            }
        }
    }
}

fn dense_components(adjacency: &[Vec<usize>]) -> (Vec<usize>, usize) {
    let mut labels = vec![usize::MAX; adjacency.len()];
    let mut count = 0;
    for root in 0..adjacency.len() {
        if labels[root] != usize::MAX {
            continue;
        }
        flood_component(adjacency, &mut labels, root, count);
        count += 1;
    }
    (labels, count)
}

fn partition_elements<T>(
    elements: Vec<TaggedDiagonal<T>>, labels: &[usize], count: usize,
) -> (Vec<Vec<TaggedDiagonal<T>>>, BTreeMap<(String, usize), usize>) {
    let mut classes: Vec<Vec<TaggedDiagonal<T>>> = (0..count).map(|_| Vec::new()).collect();
    let mut class_of = BTreeMap::new();
    for (position, element) in elements.into_iter().enumerate() {
        let class = labels[position];
        class_of.insert((element.object.clone(), element.index), class);
        classes[class].push(element);
    }
    (classes, class_of)
}

impl<T: Clone + PartialEq + Eq + std::hash::Hash> DeclaredFiniteCoend<T> {
    /// Compute the equivalence closure of recognized matched-slot pairs.
    /// Repeated object names do not duplicate tags; missing data/unknown references
    /// do not create vertices or relations. Payloads are copied, not compared.
    pub fn compute(input: &CoendInput<T>) -> Self {
        let objects = input.objects.clone();
        let contributions = input.diagonal.clone();
        let (elements, index) = tagged_elements(input);
        let (adjacency, identifications) = relation_graph(input, &index, elements.len());
        let (labels, count) = dense_components(&adjacency);
        let (classes, class_of) = partition_elements(elements, &labels, count);
        Self { objects, contributions, classes, class_of, identifications }
    }
}

// ---------------------------------------------------------------------------
// Validation: dinaturality check
// ---------------------------------------------------------------------------

/// Report only missing declared diagonal/action entries;no laws or index admission.
pub fn validate_coend_input<T: Clone + PartialEq>(input: &CoendInput<T>) -> Vec<String> {
    let mut violations = Vec::new();

    // 1. Every object has a diagonal contribution
    for obj in &input.objects {
        if !input.diagonal.contains_key(obj) {
            violations.push(format!("Missing diagonal contribution for object {}", obj));
        }
    }

    // 2. Every morphism has both actions
    for (mor_name, _, _) in &input.morphisms {
        if !input.forward_action.contains_key(mor_name) {
            violations.push(format!("Missing forward action for morphism {}", mor_name));
        }
        if !input.backward_action.contains_key(mor_name) {
            violations.push(format!("Missing backward action for morphism {}", mor_name));
        }
    }

    violations
}

fn compare_morphism_labels(
    row: &(String, String, String), forward: &[(usize, usize)], backward: &[(usize, usize)],
    labels: &TagIndex<'_>, violations: &mut Vec<String>,
) {
    let (name, source, target) = row;
    for (source_local, target_local) in matched_pairs(forward, backward) {
        match (labels.get(&(source.as_str(), source_local)), labels.get(&(target.as_str(), target_local))) {
            (Some(left), Some(right)) if left == right => {}
            (Some(left), Some(right)) => violations.push(format!(
                "Dinaturality violated: {} and {} via morphism {} mapped to different classes ({} vs {})",
                source_local, target_local, name, left, right)),
            _ => violations.push(format!(
                "Dinaturality: missing class mapping for elements involved in morphism {}", name)),
        }
    }
}

/// Compare supplied class labels for all supplied matched pairs,in row order.
/// This local diagnostic does not check class-index range,partition membership,
/// complete bifunctor laws or universal-coend provenance of a mutable raw record.
pub fn check_dinaturality<T: Clone + PartialEq>(
    coend: &DeclaredFiniteCoend<T>,
    input: &CoendInput<T>,
) -> Vec<String> {
    let labels: TagIndex<'_> = coend.class_of.iter().map(|((object, local), &class)| ((object.as_str(), *local), class)).collect();
    let mut violations = Vec::new();
    for row in &input.morphisms {
        if let (Some(forward), Some(backward)) = (input.forward_action.get(&row.0), input.backward_action.get(&row.0)) {
            compare_morphism_labels(row, forward, backward, &labels, &mut violations);
        }
    }
    violations
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trivial_coend_single_object() {
        // One object, no non-identity morphisms. Coend = F(c,c) itself.
        let input = CoendInput {
            objects: vec!["A".into()],
            morphisms: vec![],
            diagonal: {
                let mut m = BTreeMap::new();
                m.insert("A".into(), vec![1, 2, 3]);
                m
            },
            forward_action: BTreeMap::new(),
            backward_action: BTreeMap::new(),
        };

        let coend = DeclaredFiniteCoend::compute(&input);
        assert_eq!(coend.classes.len(), 3);
        assert!(coend.identifications.is_empty());
    }

    #[test]
    fn coend_with_identification() {
        // Two objects A, B with morphism f: A → B.
        // F(A,A) = {0}, F(B,B) = {1}.
        // Forward action of f sends 0 to slot 0 in F(A,B).
        // Backward action of f sends 1 to slot 0 in F(A,B).
        // So 0 ~ 1 in the coend.
        let input = CoendInput {
            objects: vec!["A".into(), "B".into()],
            morphisms: vec![("f".into(), "A".into(), "B".into())],
            diagonal: {
                let mut m = BTreeMap::new();
                m.insert("A".into(), vec![0]);
                m.insert("B".into(), vec![1]);
                m
            },
            forward_action: {
                let mut m = BTreeMap::new();
                m.insert("f".into(), vec![(0, 0)]); // element 0 of F(A,A) → slot 0
                m
            },
            backward_action: {
                let mut m = BTreeMap::new();
                m.insert("f".into(), vec![(0, 0)]); // element 0 of F(B,B) → slot 0
                m
            },
        };

        let coend = DeclaredFiniteCoend::compute(&input);
        // 0 and 1 are identified, so only 1 class.
        assert_eq!(coend.classes.len(), 1);
        assert_eq!(coend.identifications.len(), 1);
    }
}
